import{_ as s,c as t,o as n,j as e,a as r}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"《杭氏易學-易楔》簡介","description":"杭氏易學 - 《杭氏易學-易楔》簡介","frontmatter":{"title":"《杭氏易學-易楔》簡介","description":"杭氏易學 - 《杭氏易學-易楔》簡介"},"headers":[],"relativePath":"classics/hangshi/001.md","filePath":"classics/hangshi/001.md"}'),l={name:"classics/hangshi/001.md"};function i(c,a,o,d,p,h){return n(),t("div",null,[...a[0]||(a[0]=[e("h1",{id:"《杭氏易學-易楔》簡介",tabindex:"-1"},[r("《杭氏易學-易楔》簡介 "),e("a",{class:"header-anchor",href:"#《杭氏易學-易楔》簡介","aria-label":"Permalink to “《杭氏易學-易楔》簡介”"},"​")],-1),e("p",null,"《易楔》是近代易學大家杭辛齋的易學著作之一。杭辛齋，生活在1869年至1924年之間。杭辛齋在易學領域有著深厚的造詣和獨特的見解，他立足於象數，重整象數體系，企圖將象數擴展為融數學、科技、術數為一爐的無所不包的易學體系。",-1),e("p",null,"杭辛齋的易學著作包括《易楔》、《學易筆談》、《易數偶得》、《讀易雜記》等多種，這些著作合稱《杭氏易學七種》。這些作品展示了杭辛齋對《周易》象數研究的深邃見解，以及象數在自然科學方面的應用，對現代自然科學的研究具有較大的啟示作用。",-1),e("p",null,"此外，杭辛齋還組織過《周易》學術研究會，名為研幾學社，並在學社中擔任《周易》主講，撰寫《周易》講義。杭辛齋的易學思想融合了漢代易學、宋代圖書之學的特點，同時又具有世界眼光，為易學的發展開闢了新的道路。",-1),e("p",null,"總之，杭氏易學是一個具有深厚理論基礎和豐富實踐經驗的易學體系，對於研究易學和了解中國傳統文化具有重要意義。",-1)])])}const f=s(l,[["render",i]]);export{_ as __pageData,f as default};
